830 :             // choose alpha such that Hk.u = alpha ek
831 :             double akk   = jacobian[k][pk];
832 :             double alpha = (akk > 0) ? -Math.sqrt(ak2) : Math.sqrt(ak2);
833 :             double betak = 1.0 / (ak2 - akk * alpha);
