"788 :     private void qrDecomposition() throws OptimizationException {
789 : 
790 :         // initializations
791 :         for (int k = 0; k < cols; ++k) {
792 :             permutation[k] = k;
793 :             double norm2 = 0;
794 :             for (int i = 0; i < jacobian.length; ++i) {
795 :                 double akk = jacobian[i][k];
796 :                 norm2 += akk * akk;
797 :             }
798 :             jacNorm[k] = Math.sqrt(norm2);
799 :         }
800 : 
801 :         // transform the matrix column after column
802 :         for (int k = 0; k < cols; ++k) {
803 : 
804 :             // select the column with the greatest norm on active components
805 :             int nextColumn = -1;
806 :             double ak2 = Double.NEGATIVE_INFINITY;
807 :             for (int i = k; i < cols; ++i) {
808 :                 double norm2 = 0;
809 :                 for (int j = k; j < jacobian.length; ++j) {
810 :                     double aki = jacobian[j][permutation[i]];
811 :                     norm2 += aki * aki;
812 :                 }
813 :                 if (Double.isInfinite(norm2) || Double.isNaN(norm2)) {
814 :                     throw new OptimizationException(LocalizedFormats.UNABLE_TO_PERFORM_QR_DECOMPOSITION_ON_JACOBIAN,
815 :                             rows, cols);
816 :                 }
817 :                 if (norm2 > ak2) {
818 :                     nextColumn = i;
819 :                     ak2        = norm2;
820 :                 }
821 :             }
822 :             if (ak2 <= qrRankingThreshold) {
823 :                 rank = k;
824 :                 return;
825 :             }
826 :             int pk                  = permutation[nextColumn];
827 :             permutation[nextColumn] = permutation[k];
828 :             permutation[k]          = pk;
829 : 
830 :             // choose alpha such that Hk.u = alpha ek
831 :             double akk   = jacobian[k][pk];
832 :             double alpha = (akk > 0) ? -Math.sqrt(ak2) : Math.sqrt(ak2);
833 :             double betak = 1.0 / (ak2 - akk * alpha);
834 :             beta[pk]     = betak;
835 : 
836 :             // transform the current column
837 :             diagR[pk]        = alpha;
838 :             jacobian[k][pk] -= alpha;
839 : 
840 :             // transform the remaining columns
841 :             for (int dk = cols - 1 - k; dk > 0; --dk) {
842 :                 double gamma = 0;
843 :                 for (int j = k; j < jacobian.length; ++j) {
844 :                     gamma += jacobian[j][pk] * jacobian[j][permutation[k + dk]];
845 :                 }
846 :                 gamma *= betak;
847 :                 for (int j = k; j < jacobian.length; ++j) {
848 :                     jacobian[j][permutation[k + dk]] -= gamma * jacobian[j][pk];
849 :                 }
850 :             }
851 : 
852 :         }
853 : 
854 :         rank = solvedCols;
855 : 
856 :     }"

