"493 :     private void determineLMParameter(double[] qy, double delta, double[] diag,
494 :             double[] work1, double[] work2, double[] work3) {
495 : 
496 :         // compute and store in x the gauss-newton direction, if the
497 :         // jacobian is rank-deficient, obtain a least squares solution
498 :         for (int j = 0; j < rank; ++j) {
499 :             lmDir[permutation[j]] = qy[j];
500 :         }
501 :         for (int j = rank; j < cols; ++j) {
502 :             lmDir[permutation[j]] = 0;
503 :         }
504 :         for (int k = rank - 1; k >= 0; --k) {
505 :             int pk = permutation[k];
506 :             double ypk = lmDir[pk] / diagR[pk];
507 :             for (int i = 0; i < k; ++i) {
508 :                 lmDir[permutation[i]] -= ypk * jacobian[i][pk];
509 :             }
510 :             lmDir[pk] = ypk;
511 :         }
512 : 
513 :         // evaluate the function at the origin, and test
514 :         // for acceptance of the Gauss-Newton direction
515 :         double dxNorm = 0;
516 :         for (int j = 0; j < solvedCols; ++j) {
517 :             int pj = permutation[j];
518 :             double s = diag[pj] * lmDir[pj];
519 :             work1[pj] = s;
520 :             dxNorm += s * s;
521 :         }
522 :         dxNorm = Math.sqrt(dxNorm);
523 :         double fp = dxNorm - delta;
524 :         if (fp <= 0.1 * delta) {
525 :             lmPar = 0;
526 :             return;
527 :         }
528 : 
529 :         // if the jacobian is not rank deficient, the Newton step provides
530 :         // a lower bound, parl, for the zero of the function,
531 :         // otherwise set this bound to zero
532 :         double sum2;
533 :         double parl = 0;
534 :         if (rank == solvedCols) {
535 :             for (int j = 0; j < solvedCols; ++j) {
536 :                 int pj = permutation[j];
537 :                 work1[pj] *= diag[pj] / dxNorm;
538 :             }
539 :             sum2 = 0;
540 :             for (int j = 0; j < solvedCols; ++j) {
541 :                 int pj = permutation[j];
542 :                 double sum = 0;
543 :                 for (int i = 0; i < j; ++i) {
544 :                     sum += jacobian[i][pj] * work1[permutation[i]];
545 :                 }
546 :                 double s = (work1[pj] - sum) / diagR[pj];
547 :                 work1[pj] = s;
548 :                 sum2 += s * s;
549 :             }
550 :             parl = fp / (delta * sum2);
551 :         }
552 : 
553 :         // calculate an upper bound, paru, for the zero of the function
554 :         sum2 = 0;
555 :         for (int j = 0; j < solvedCols; ++j) {
556 :             int pj = permutation[j];
557 :             double sum = 0;
558 :             for (int i = 0; i <= j; ++i) {
559 :                 sum += jacobian[i][pj] * qy[i];
560 :             }
561 :             sum /= diag[pj];
562 :             sum2 += sum * sum;
563 :         }
564 :         double gNorm = Math.sqrt(sum2);
565 :         double paru = gNorm / delta;
566 :         if (paru == 0) {
567 :             // 2.2251e-308 is the smallest positive real for IEE754
568 :             paru = 2.2251e-308 / Math.min(delta, 0.1);
569 :         }
570 : 
571 :         // if the input par lies outside of the interval (parl,paru),
572 :         // set par to the closer endpoint
573 :         lmPar = Math.min(paru, Math.max(lmPar, parl));
574 :         if (lmPar == 0) {
575 :             lmPar = gNorm / dxNorm;
576 :         }
577 : 
578 :         for (int countdown = 10; countdown >= 0; --countdown) {
579 : 
580 :             // evaluate the function at the current value of lmPar
581 :             if (lmPar == 0) {
582 :                 lmPar = Math.max(2.2251e-308, 0.001 * paru);
583 :             }
584 :             double sPar = Math.sqrt(lmPar);
585 :             for (int j = 0; j < solvedCols; ++j) {
586 :                 int pj = permutation[j];
587 :                 work1[pj] = sPar * diag[pj];
588 :             }
589 :             determineLMDirection(qy, work1, work2, work3);
590 : 
591 :             dxNorm = 0;
592 :             for (int j = 0; j < solvedCols; ++j) {
593 :                 int pj = permutation[j];
594 :                 double s = diag[pj] * lmDir[pj];
595 :                 work3[pj] = s;
596 :                 dxNorm += s * s;
597 :             }
598 :             dxNorm = Math.sqrt(dxNorm);
599 :             double previousFP = fp;
600 :             fp = dxNorm - delta;
601 : 
602 :             // if the function is small enough, accept the current value
603 :             // of lmPar, also test for the exceptional cases where parl is zero
604 :             if ((Math.abs(fp) <= 0.1 * delta) ||
605 :                     ((parl == 0) && (fp <= previousFP) && (previousFP < 0))) {
606 :                 return;
607 :             }
608 : 
609 :             // compute the Newton correction
610 :             for (int j = 0; j < solvedCols; ++j) {
611 :                 int pj = permutation[j];
612 :                 work1[pj] = work3[pj] * diag[pj] / dxNorm;
613 :             }
614 :             for (int j = 0; j < solvedCols; ++j) {
615 :                 int pj = permutation[j];
616 :                 work1[pj] /= work2[j];
617 :                 double tmp = work1[pj];
618 :                 for (int i = j + 1; i < solvedCols; ++i) {
619 :                     work1[permutation[i]] -= jacobian[i][pj] * tmp;
620 :                 }
621 :             }
622 :             sum2 = 0;
623 :             for (int j = 0; j < solvedCols; ++j) {
624 :                 double s = work1[permutation[j]];
625 :                 sum2 += s * s;
626 :             }
627 :             double correction = fp / (delta * sum2);
628 : 
629 :             // depending on the sign of the function, update parl or paru.
630 :             if (fp > 0) {
631 :                 parl = Math.max(parl, lmPar);
632 :             } else if (fp < 0) {
633 :                 paru = Math.min(paru, lmPar);
634 :             }
635 : 
636 :             // compute an improved estimate for lmPar
637 :             lmPar = Math.max(parl, lmPar + correction);
638 : 
639 :         }
